import{_ as a,o as t,c as i,ae as l}from"./chunks/framework.RRduUuAx.js";const h=JSON.parse('{"title":"Rollback Automation, Canary Upgrade Process, and Tests","description":"","frontmatter":{"work_package_id":"WP02","title":"Rollback Automation, Canary Upgrade Process, and Tests","lane":"done","dependencies":["WP01"],"base_branch":"020-prerelease-dependency-registry-WP01","base_commit":"9c9e923a078db724d846fc05a09523d0187f345c","created_at":"2026-03-01T13:31:46.174773+00:00","subtasks":["T006","T007","T008","T009","T010","T011"],"phase":"Phase 1 - Dependency Tracking","assignee":"","agent":"claude-haiku","shell_pid":"64058","review_status":"approved","reviewed_by":"Koosha Paridehpour","history":[{"timestamp":"2026-02-27T00:00:00Z","lane":"planned","agent":"system","shell_pid":"","action":"Prompt generated via /spec-kitty.tasks"}]},"headers":[],"relativePath":"specs/020-prerelease-dependency-registry/tasks/WP02-rollback-and-canary-process.md","filePath":"specs/020-prerelease-dependency-registry/tasks/WP02-rollback-and-canary-process.md"}'),o={name:"specs/020-prerelease-dependency-registry/tasks/WP02-rollback-and-canary-process.md"};function s(r,e,n,c,d,p){return t(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="work-package-prompt-wp02-rollback-automation-canary-upgrade-process-and-tests" tabindex="-1">Work Package Prompt: WP02 - Rollback Automation, Canary Upgrade Process, and Tests <a class="header-anchor" href="#work-package-prompt-wp02-rollback-automation-canary-upgrade-process-and-tests" aria-label="Permalink to &quot;Work Package Prompt: WP02 - Rollback Automation, Canary Upgrade Process, and Tests&quot;">​</a></h1><h2 id="objectives-success-criteria" tabindex="-1">Objectives &amp; Success Criteria <a class="header-anchor" href="#objectives-success-criteria" aria-label="Permalink to &quot;Objectives &amp; Success Criteria&quot;">​</a></h2><ul><li>Deliver atomic rollback to the last known-good pin for any tracked prerelease dependency.</li><li>Deliver a canary upgrade process that tests prerelease bumps in isolation before merging.</li><li>Ensure every upgrade attempt (success or failure) is recorded in the structured changelog.</li><li>Comprehensive integration tests for both rollback and canary workflows.</li></ul><p>Success criteria:</p><ul><li><code>bun run deps:rollback &lt;package&gt;</code> reverts to last known-good pin atomically with passing gates.</li><li>Canary process creates an isolated branch, upgrades, runs all gates, and auto-merges or opens issue.</li><li>Every upgrade attempt is recorded in <code>deps-changelog.json</code>.</li><li>Rollback completes in &lt; 60 seconds including lockfile regeneration.</li><li>Canary does not block unrelated CI pipelines.</li></ul><h2 id="context-constraints" tabindex="-1">Context &amp; Constraints <a class="header-anchor" href="#context-constraints" aria-label="Permalink to &quot;Context &amp; Constraints&quot;">​</a></h2><ul><li>Constitution: <code>docs/reference/constitution.md</code></li><li>Plan: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/020-prerelease-dependency-registry/plan.md</code></li><li>Spec: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/020-prerelease-dependency-registry/spec.md</code></li><li>WP01 output: <code>deps-registry.json</code>, <code>deps-changelog.json</code>, <code>scripts/deps-types.ts</code>, <code>scripts/deps-status.ts</code>, <code>scripts/deps-changelog-util.ts</code>.</li></ul><p>Constraints:</p><ul><li>Rollback must be atomic: full reversion or no changes (FR-005).</li><li>Canary must not block unrelated CI (NFR-003).</li><li>Per-workspace deterministic pinning must be maintained (FR-003).</li><li>Keep files under repository limits (target &lt;=350 lines, hard &lt;=500).</li></ul><p>Implementation command:</p><ul><li><code>spec-kitty implement WP02</code></li></ul><h2 id="subtasks-detailed-guidance" tabindex="-1">Subtasks &amp; Detailed Guidance <a class="header-anchor" href="#subtasks-detailed-guidance" aria-label="Permalink to &quot;Subtasks &amp; Detailed Guidance&quot;">​</a></h2><h3 id="subtask-t006-implement-atomic-rollback-command" tabindex="-1">Subtask T006 - Implement atomic rollback command <a class="header-anchor" href="#subtask-t006-implement-atomic-rollback-command" aria-label="Permalink to &quot;Subtask T006 - Implement atomic rollback command&quot;">​</a></h3><ul><li>Purpose: Provide a single command to safely revert a breaking prerelease dependency to the last known-good pin.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/scripts/deps-rollback.ts</code>.</li><li>Accept a package name as a required CLI argument: <code>bun run deps:rollback &lt;package&gt;</code>.</li><li>Read <code>deps-registry.json</code> and locate the target dependency entry.</li><li>Extract the most recent entry from <code>knownGoodHistory</code> that is different from the current pin.</li><li>Implement atomic rollback: a. Copy the current lockfile to a backup location. b. Update <code>package.json</code> (root and/or workspace) to pin the target dependency to the known-good version. c. Run <code>bun install</code> to regenerate the lockfile. d. Run <code>bun run typecheck</code> as a smoke check. e. If typecheck passes: update <code>deps-registry.json</code> currentPin to the rollback version, append a changelog entry via the utility from WP01. f. If typecheck fails or any step fails: restore the backup lockfile and revert package.json changes. Print error with details.</li><li>Ensure only the target dependency changes in the lockfile — diff the lockfile before committing to verify no unrelated changes.</li><li>Handle edge cases: package not found in manifest, no known-good version available, lockfile backup/restore failures.</li><li>Add <code>deps:rollback</code> script entry to root <code>package.json</code>.</li><li>Print a summary: rolled back from version X to version Y, gates passed/failed, changelog entry ID.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/scripts/deps-rollback.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/package.json</code> (script entry)</li></ul></li><li>Acceptance: <ul><li>Rollback reverts to known-good pin with passing typecheck.</li><li>Atomic: failure at any step restores original state.</li><li>Completes in &lt; 60 seconds including lockfile regen.</li><li>Changelog entry recorded.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t007-implement-canary-upgrade-process" tabindex="-1">Subtask T007 - Implement canary upgrade process <a class="header-anchor" href="#subtask-t007-implement-canary-upgrade-process" aria-label="Permalink to &quot;Subtask T007 - Implement canary upgrade process&quot;">​</a></h3><ul><li>Purpose: Automate the testing of prerelease upgrades in isolation so safe upgrades are merged automatically and risky ones are flagged.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/scripts/deps-canary.ts</code>.</li><li>Accept optional package name argument; if omitted, check all tracked dependencies for available upgrades.</li><li>For each dependency with an available upgrade: a. Create an isolated git branch: <code>canary/&lt;package&gt;-&lt;version&gt;-&lt;timestamp&gt;</code>. b. Update the dependency pin in the appropriate <code>package.json</code>. c. Run <code>bun install</code> to regenerate the lockfile. d. Run the full quality gate suite via <code>bun run gates</code> (spec 021). e. Collect structured gate results (JSON output from each gate).</li><li>On all gates passing: a. Commit the changes with a structured message: <code>chore(deps): upgrade &lt;package&gt; from &lt;old&gt; to &lt;new&gt; [canary]</code>. b. Push the branch and create a PR targeting the configured base branch. c. If auto-merge is enabled, merge the PR. d. Update <code>deps-registry.json</code>: set new currentPin, add to knownGoodHistory. e. Append a success entry to <code>deps-changelog.json</code>.</li><li>On any gate failing: a. Do not merge. Open a GitHub issue with: package name, attempted version, failing gates with details, and the canary branch ref. b. Append a failure entry to <code>deps-changelog.json</code> with gate failure details.</li><li>Ensure the canary process runs in its own CI job/context and does not block other pipelines.</li><li>Support a <code>--dry-run</code> flag that reports what would be upgraded without making changes.</li><li>Handle edge cases: no upgrades available (exit 0 with message), git branch conflicts, CI timeout.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/scripts/deps-canary.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/package.json</code> (script entry)</li></ul></li><li>Acceptance: <ul><li>Canary creates isolated branch, runs gates, merges on pass, opens issue on fail.</li><li>Structured changelog entries for all outcomes.</li><li>Does not block unrelated CI pipelines.</li><li>Dry-run mode works without side effects.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t008-wire-canary-results-into-changelog" tabindex="-1">Subtask T008 - Wire canary results into changelog <a class="header-anchor" href="#subtask-t008-wire-canary-results-into-changelog" aria-label="Permalink to &quot;Subtask T008 - Wire canary results into changelog&quot;">​</a></h3><ul><li>Purpose: Ensure every canary run outcome is recorded in the structured dependency changelog for auditability.</li><li>Steps: <ol><li>Import and use the <code>appendChangelogEntry</code> utility from <code>scripts/deps-changelog-util.ts</code> in the canary script.</li><li>On canary success: record entry with <code>outcome: &quot;success&quot;</code>, all gate results, branch ref, and PR URL.</li><li>On canary failure: record entry with <code>outcome: &quot;failure&quot;</code>, failing gate details, issue URL.</li><li>On canary skip (no upgrade available): record entry with <code>outcome: &quot;skipped&quot;</code> and reason.</li><li>Verify changelog entries are appended atomically even when multiple canary runs execute concurrently.</li><li>Add a <code>bun run deps:log</code> convenience command that pretty-prints the changelog.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/scripts/deps-canary.ts</code> (integration)</li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/scripts/deps-changelog-util.ts</code> (may need updates)</li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/package.json</code> (deps:log script entry)</li></ul></li><li>Acceptance: <ul><li>Every canary outcome produces a changelog entry.</li><li>Changelog entries are complete and valid per schema.</li><li><code>bun run deps:log</code> displays the changelog readably.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t009-add-rollback-integration-tests" tabindex="-1">Subtask T009 - Add rollback integration tests <a class="header-anchor" href="#subtask-t009-add-rollback-integration-tests" aria-label="Permalink to &quot;Subtask T009 - Add rollback integration tests&quot;">​</a></h3><ul><li>Purpose: Validate the rollback workflow end-to-end with simulated dependency breakage.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/scripts/tests/deps-rollback.test.ts</code>.</li><li>Test: given a manifest with a known-good history, rollback to the previous pin updates the manifest and lockfile correctly.</li><li>Test: given a rollback where lockfile regeneration fails, the original lockfile is restored and no manifest changes are persisted.</li><li>Test: given a package not in the manifest, rollback exits with a clear error and no file changes.</li><li>Test: given a package with no known-good history (only one version ever), rollback exits with a clear error.</li><li>Test: given a successful rollback, a changelog entry is appended with correct fields.</li><li>Test: lockfile diff after rollback shows only the target dependency changed.</li><li>Use fixture files and mocked <code>bun install</code> / <code>bun run typecheck</code> to make tests deterministic and fast.</li><li>Ensure tests clean up any temporary files or backup copies.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/scripts/tests/deps-rollback.test.ts</code></li></ul></li><li>Acceptance: <ul><li>All rollback scenarios covered (success, failure, edge cases).</li><li>Tests are deterministic and fast.</li><li>No flakiness or leftover artifacts.</li></ul></li><li>Parallel: Yes (after T006 is functional).</li></ul><h3 id="subtask-t010-add-canary-integration-tests" tabindex="-1">Subtask T010 - Add canary integration tests <a class="header-anchor" href="#subtask-t010-add-canary-integration-tests" aria-label="Permalink to &quot;Subtask T010 - Add canary integration tests&quot;">​</a></h3><ul><li>Purpose: Validate the canary upgrade workflow end-to-end with simulated upgrade scenarios.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/scripts/tests/deps-canary.test.ts</code>.</li><li>Test: given an available upgrade that passes all gates, the canary creates a branch, commits, and records a success changelog entry.</li><li>Test: given an available upgrade that fails a gate, the canary does not merge, opens an issue, and records a failure changelog entry.</li><li>Test: given no available upgrades, the canary exits cleanly with a skip changelog entry.</li><li>Test: dry-run mode reports the planned upgrade without creating branches or modifying files.</li><li>Test: canary handles git branch naming conflicts gracefully.</li><li>Test: canary handles registry unreachable gracefully (skip with warning).</li><li>Mock git operations, CI gate execution, and GitHub API calls for deterministic testing.</li><li>Verify the canary process does not modify the working directory of unrelated CI jobs.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/scripts/tests/deps-canary.test.ts</code></li></ul></li><li>Acceptance: <ul><li>All canary scenarios covered (pass, fail, skip, dry-run, errors).</li><li>Tests are deterministic via mocking.</li><li>No side effects on the host filesystem or git state.</li></ul></li><li>Parallel: Yes (after T007 is functional).</li></ul><h3 id="subtask-t011-validate-nfr-performance-compliance" tabindex="-1">Subtask T011 - Validate NFR performance compliance <a class="header-anchor" href="#subtask-t011-validate-nfr-performance-compliance" aria-label="Permalink to &quot;Subtask T011 - Validate NFR performance compliance&quot;">​</a></h3><ul><li>Purpose: Confirm the rollback and canary workflows meet the non-functional requirements for speed and isolation.</li><li>Steps: <ol><li>Measure rollback execution time including lockfile regeneration and verify &lt; 60 seconds.</li><li>Measure status command execution time with warm cache and verify &lt; 10 seconds.</li><li>Verify canary runs in isolation: start an unrelated CI job concurrently and confirm it is not blocked or delayed.</li><li>Document all measurements with environment details.</li><li>If any NFR is not met, identify the bottleneck and document mitigation.</li></ol></li><li>Files: <ul><li>No new files; measurements documented in PR description.</li></ul></li><li>Acceptance: <ul><li>All NFR targets met or documented with mitigation plans.</li></ul></li><li>Parallel: No.</li></ul><h2 id="test-strategy" tabindex="-1">Test Strategy <a class="header-anchor" href="#test-strategy" aria-label="Permalink to &quot;Test Strategy&quot;">​</a></h2><ul><li>Vitest integration tests with mocked external dependencies (git, registries, CI).</li><li>Fixture-based rollback tests with known-good and failure scenarios.</li><li>Deterministic canary tests via mocked gate execution.</li><li>Performance measurements for NFR compliance.</li></ul><h2 id="risks-mitigations" tabindex="-1">Risks &amp; Mitigations <a class="header-anchor" href="#risks-mitigations" aria-label="Permalink to &quot;Risks &amp; Mitigations&quot;">​</a></h2><ul><li>Risk: Lockfile regeneration changes unrelated dependencies.</li><li>Mitigation: Diff lockfile before/after; reject if non-target dependencies changed.</li><li>Risk: Canary branch conflicts with existing branches.</li><li>Mitigation: Include timestamp in branch name; handle conflict by appending suffix.</li></ul><h2 id="review-guidance" tabindex="-1">Review Guidance <a class="header-anchor" href="#review-guidance" aria-label="Permalink to &quot;Review Guidance&quot;">​</a></h2><ul><li>Confirm rollback is truly atomic (no partial state on failure).</li><li>Confirm canary runs in isolation without blocking other CI.</li><li>Confirm all changelog entries are complete and schema-valid.</li><li>Confirm edge cases are handled (missing package, no history, unreachable registry).</li></ul><h2 id="activity-log" tabindex="-1">Activity Log <a class="header-anchor" href="#activity-log" aria-label="Permalink to &quot;Activity Log&quot;">​</a></h2><ul><li>2026-02-27T00:00:00Z – system – lane=planned – Prompt created.</li><li>2026-03-01T13:31:46Z – claude-haiku – shell_pid=64058 – lane=doing – Assigned agent via workflow command</li><li>2026-03-01T13:33:19Z – claude-haiku – shell_pid=64058 – lane=done – Implemented</li></ul>',32)])])}const g=a(o,[["render",s]]);export{h as __pageData,g as default};
